    @Override public void onCreate(Bundle stateBundle) {
        store=new Store(this);ThemePalette palette=ThemePalette.load(this,store.prefs);
        setTheme(ThemePalette.style(palette.dark,store.prefs.getString("accent","Blue")));
        super.onCreate(stateBundle);applyColors();if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::handleBack);
        connectivity=(ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);
        networkIdentity=connectionIdentity();
        networkCallback=new ConnectivityManager.NetworkCallback(){
            @Override public void onAvailable(Network n){networkChanged();}
            @Override public void onLost(Network n){networkChanged();}
            @Override public void onLinkPropertiesChanged(Network n,android.net.LinkProperties p){networkChanged();}
            @Override public void onCapabilitiesChanged(Network n,android.net.NetworkCapabilities c){networkChanged();}
        };
        try{connectivity.registerNetworkCallback(new NetworkRequest.Builder().clearCapabilities().build(),networkCallback);}catch(Exception ignored){}
        Bundle themed=getIntent().getBundleExtra("theme_state");getIntent().removeExtra("theme_state");if(themed!=null)restoreScreen(themed);else if(stateBundle!=null)restoreScreen(stateBundle);else if(!restoreLastScreen())showDashboard();
    }
    @Override protected void onStart(){super.onStart();visible=true;refreshNetworkPickers();if(lanDetected!=null)updateDetectedLan();if(page.equals("dashboard")||kind.equals("network")){final long gen=generation;handler.postDelayed(()->{if(gen==generation&&visible&&!running&&(page.equals("dashboard")||kind.equals("network")))refreshDashboard(false);},300);scheduleDashboard();}}
    @Override protected void onStop(){visible=false;rememberInputs();persistScreen();stopWork("Paused · results kept on this phone");super.onStop();}
    @Override protected void onDestroy(){stopWork("");worker.shutdownNow();try{connectivity.unregisterNetworkCallback(networkCallback);}catch(Exception ignored){}super.onDestroy();}
    @Override public void onBackPressed(){handleBack();}
    private void handleBack(){if(running){persistScreen();stopWork("Stopped · results kept");return;}if(lanTargetEditor!=null&&lanTargetEditor.getVisibility()==View.VISIBLE){setLanEditorExpanded(false);return;}if(!page.equals("dashboard")){showDashboard();return;}persistScreen();moveTaskToBack(true);}
    private String connectionIdentity(){try{StringBuilder identity=new StringBuilder();for(NetworkInventory.Connection c:NetworkInventory.snapshot(this))identity.append(c.id).append('/').append(c.title()).append('/').append(java.util.Arrays.toString(c.cidrs())).append('/').append(c.validated).append(';');return identity.toString();}catch(Exception e){return "";}}
    private void networkChanged(){handler.post(()->{if(networkRefresh!=null)handler.removeCallbacks(networkRefresh);networkRefresh=()->{String identity=connectionIdentity();if(identity.equals(networkIdentity))return;networkIdentity=identity;refreshNetworkPickers();if(lanDetected!=null)updateDetectedLan();if(visible&&(page.equals("dashboard")||kind.equals("network"))&&!running)refreshDashboard(false);};handler.postDelayed(networkRefresh,500);});}
