    private void rememberInputs(){if(store==null||inputs.isEmpty()||page.equals("settings"))return;android.content.SharedPreferences.Editor e=store.prefs.edit();for(Map.Entry<String,View> input:inputs.entrySet()){String key=input.getKey();if(input.getValue() instanceof CheckBox)e.putBoolean(key,yes(key));else e.putString(key,value(key));}for(Map.Entry<String,NetworkPicker> item:networkPickers.entrySet())e.putString(item.getKey()+"_label",item.getValue().selectedLabel);if(page.equals("tool"))e.putString("draft_"+kind,config().toString());e.apply();}
    private boolean retainedTool(String value){return value.equals("lan")||value.equals("wifi")||value.equals("signal");}
    private void persistScreen(){
        if(store==null||content==null)return;persistSnapshot();JSONObject saved=new JSONObject();try{saved.put("page",page).put("kind",kind).put("config",config()).put("scroll",scroll==null?0:scroll.getScrollY());store.uiState(saved);}catch(Exception ignored){}
    }
    private void persistSnapshot(){
        if(!retainedTool(kind)||!page.equals("tool")||snapshotRestored)return;Report report=latestReport!=null?latestReport:current;if(report==null)return;JSONObject cfg=currentJobConfig!=null?currentJobConfig:config();store.snapshot(kind,report,cfg);
    }
    private boolean restoreLastScreen(){
        JSONObject saved=store.uiState();if(saved==null||saved.length()==0)return false;String p=saved.optString("page","dashboard"),k=saved.optString("kind","");JSONObject cfg=saved.optJSONObject("config");
        if(p.equals("tool")&&retainedTool(k))showTool(k,"",cfg);else if(p.equals("tools"))showTools();else if(p.equals("more"))showMore();else return false;
        final int y=saved.optInt("scroll",0);if(scroll!=null)scroll.post(()->scroll.scrollTo(0,y));return true;
    }
    private void restoreSnapshot(String key){
        JSONObject saved=store.snapshot(key);if(saved==null)return;JSONObject data=saved.optJSONObject("report");if(data==null){restoreHistorySnapshot(key);return;}try{Report report=Report.from(data);snapshotRestored=true;snapshotSavedAt=saved.optLong("savedAt",report.timestamp);currentJobConfig=saved.optJSONObject("cfg");currentJobReportId=report.id;renderResult(report);latestReport=report;if(state!=null)state.setText("Saved "+shortDate(snapshotSavedAt)+" · tap "+(key.equals("wifi")?"Scan":key.equals("lan")?"Scan LAN":"Monitor")+" to update");}catch(Exception ignored){}
    }
    private void restoreHistorySnapshot(String key){final long gen=generation,op=operation;worker.execute(()->{Report previous=store.latestResult(key);if(previous==null)return;handler.post(()->{if(gen!=generation||op!=operation||running||current!=null||!kind.equals(key))return;JSONObject cfg=configurationFor(previous);store.snapshot(key,previous,cfg,previous.timestamp);restoreSnapshot(key);});});}
    private String shortDate(long value){return DateFormat.getDateTimeInstance(DateFormat.SHORT,DateFormat.SHORT).format(new java.util.Date(value));}
    @Override protected void onSaveInstanceState(Bundle out){rememberInputs();persistScreen();saveScreen(out);super.onSaveInstanceState(out);}
    private void saveScreen(Bundle out){out.putString("page",page);out.putString("kind",kind);out.putString("config",config().toString());out.putInt("scroll",scroll==null?0:scroll.getScrollY());out.putString("filter",filter);out.putBoolean("open_only",openOnly!=null&&openOnly.isChecked());out.putString("export_ext",pendingExt);out.putString("export_mime",pendingMime);Report captured=latestReport!=null?latestReport:current;if(captured!=null){String report=captured.json().toString();out.putLong("captured_at",System.currentTimeMillis());if(report.length()<400000)out.putString("report",report);else{store.save(captured);out.putString("report_id",captured.id);}}}
    private void restoreScreen(Bundle data){
        restoring=true;String p=data.getString("page","dashboard"),k=data.getString("kind","");JSONObject cfg=null;Report r=null;long capturedAt=data.getLong("captured_at",0);
        try{cfg=new JSONObject(data.getString("config","{}"));String body=data.getString("report","");if(!body.isEmpty())r=Report.from(new JSONObject(body));else if(data.containsKey("report_id"))for(Report old:store.history())if(old.id.equals(data.getString("report_id"))){r=old;break;}}catch(Exception ignored){}
        if(p.equals("tool"))showTool(k,"",cfg);else if(p.equals("tools"))showTools();else if(p.equals("history"))showHistory();else if(p.equals("favorites"))showFavorites();else if(p.equals("settings")){restore=cfg;showSettings();restore=null;}else if(p.equals("more"))showMore();else if(p.equals("saved")&&r!=null)showSaved(r);else showDashboard();restoring=false;
        boolean cached=false;if(p.equals("tool")&&retainedTool(k)&&current!=null){Report retained=current;cached=r==null||(capturedAt>0?snapshotSavedAt>=capturedAt:retained.id.equals(r.id)?rowCount(retained)>=rowCount(r):retained.timestamp>=r.timestamp);if(cached)r=retained;}
        filter=data.getString("filter","");if(data.getBoolean("open_only",false)){openOnly=new CheckBox(this);openOnly.setChecked(true);}pendingExt=data.getString("export_ext","");pendingMime=data.getString("export_mime","");if(r!=null&&!pendingExt.isEmpty())pendingExport=pendingExt.equals("csv")?r.csv():pendingExt.equals("json")?r.json().toString():r.text();
        if(r!=null&&resultRows!=null){if(retainedTool(k)&&p.equals("tool")){latestReport=r;currentJobReportId=r.id;if(!cached){currentJobConfig=cfg;snapshotSavedAt=capturedAt>0?capturedAt:r.timestamp;store.snapshot(k,r,cfg,snapshotSavedAt);}snapshotRestored=true;}renderResult(r);if(state!=null)state.setText(retainedTool(k)?"Saved "+shortDate(snapshotSavedAt)+" · refresh when ready":"Previous result · ready to run again");}
        final int y=data.getInt("scroll",0);if(scroll!=null)scroll.post(()->scroll.scrollTo(0,y));
    }
