        ArrayAdapter<NetworkChoice> adapter=new ArrayAdapter<NetworkChoice>(this,android.R.layout.simple_spinner_item,picker.choices){
            @Override public View getView(int position,View recycled,ViewGroup parent){TextView v=(TextView)super.getView(position,recycled,parent);v.setTextColor(ink);v.setTextSize(14);v.setSingleLine(true);v.setEllipsize(TextUtils.TruncateAt.END);v.setPadding(d(2),0,d(2),0);return v;}
            @Override public View getDropDownView(int position,View recycled,ViewGroup parent){TextView v=(TextView)super.getDropDownView(position,recycled,parent);v.setTextColor(ink);v.setTextSize(14);v.setSingleLine(false);v.setMaxLines(3);v.setMinimumHeight(d(56));v.setPadding(d(16),d(10),d(16),d(10));return v;}
        };adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);picker.spinner.setAdapter(adapter);picker.spinner.setSelection(chosen);NetworkChoice choice=picker.choices.get(chosen);picker.selectedKey=choice.key;picker.selectedLabel=choice.label;
