    private NetworkChoice selectedNetwork(String key){
        NetworkPicker picker=networkPickers.get(key);if(picker==null)return null;NetworkChoice chosen=picker.selected();if(chosen==null)return null;if(!chosen.available)throw new IllegalArgumentException("The selected network is disconnected. Choose a connected network or System default routing.");
        if(!chosen.key.isEmpty())return chosen;if(!picker.lan)return chosen;
        List<NetworkInventory.Connection> connections=NetworkInventory.snapshot(this);NetworkInventory.Connection automatic=null;
        for(NetworkInventory.Connection connection:connections)if(connection.canBind()&&(connection.kind.equals("Wi-Fi")||connection.kind.equals("Ethernet"))&&connection.ipv4Cidrs.length>0){automatic=connection;break;}
        if(automatic==null)for(NetworkInventory.Connection connection:connections)if((connection.kind.equals("Wi-Fi")||connection.kind.equals("Ethernet"))&&connection.ipv4Cidrs.length>0){automatic=connection;break;}
        if(automatic==null)for(NetworkInventory.Connection connection:connections)if(connection.defaultNetwork){automatic=connection;break;}
        if(automatic==null)return chosen;String source=automatic.ipv4Cidrs.length==0?"":automatic.ipv4Cidrs[0];return new NetworkChoice(automatic.kind+"|"+automatic.interfaceName+"|"+source,automatic.id,automatic.title(),automatic.recommendedRange(),automatic.firstIpv4(),automatic.gateway(),automatic.kind,true);
    }
