    private void applyTargetSuggestion(TargetSuggestion suggestion){
        if(targetInput==null||running)return;targetInput.setText(suggestion.host);NetworkPicker picker=networkPickers.get("outgoing_network");if(picker!=null&&suggestion.route!=null){String key=suggestion.route.optString("outgoing_network",suggestion.route.optString("network_key","")),id=suggestion.route.optString("network_id","");if(key.isEmpty()&&!id.isEmpty()){NetworkInventory.Connection connection=NetworkInventory.lookup(this,id);if(connection!=null)key=connectionConfiguration(connection).optString("outgoing_network","");else key="unavailable:"+id;}picker.selectedKey=key;picker.selectedLabel=suggestion.route.optString("outgoing_network_label",suggestion.route.optString("network_label","Saved network"));populateNetworkPicker(picker);}if(kind.equals("dns")&&(suggestion.host.contains(":")||suggestion.host.matches("[0-9.]+"))){View type=inputs.get("dns_type");if(type instanceof Spinner){Spinner spinner=(Spinner)type;for(int i=0;i<spinner.getCount();i++)if(String.valueOf(spinner.getItemAtPosition(i)).equals("PTR")){spinner.setSelection(i);break;}}}rememberInputs();toast("Target selected · "+suggestion.host);
    }
