    private Report monitorSignal(Task t)throws Exception{
        Report r=new Report("Wi-Fi signal monitor","Connected Wi-Fi","Time","RSSI dBm","Connection");String lastConnection="";long started=android.os.SystemClock.elapsedRealtime();
        r.note("Live samples from Android Wi-Fi information; gaps indicate unavailable / redacted signal. Monitoring stops in the background.");
        while(!t.isCancelled()){
            t.check();Report dash=AndroidNetwork.dashboard(this,new Task(null));String dbm="Unavailable",connection="";
            synchronized(dash){for(List<String>row:dash.rows){if(row.size()>1&&row.get(0).equals("Wi-Fi RSSI"))dbm=row.get(1);if(row.size()>1&&(row.get(0).contains("SSID")||row.get(0).contains("BSSID")||row.get(0).equals("Wi-Fi frequency")))connection+=row.get(0)+": "+row.get(1)+" · ";}}
            double v=parse(dbm,Double.NaN);if(v>0||v<-150)v=Double.NaN;r.add(DateFormat.getTimeInstance().format(new java.util.Date()),dbm,connection);synchronized(r){if(r.rows.size()>10000)r.rows.remove(0);}r.series("RSSI",v);r.series("Elapsed seconds",(android.os.SystemClock.elapsedRealtime()-started)/1000.0);
            if(!connection.equals(lastConnection)){r.note("Connection changed: "+connection);lastConnection=connection;}
            t.emit(r);t.sleep(3000);
        }return r;
    }
    private void runJob(String name,Job job,boolean save,JSONObject cfg){
        if(running)return;snapshotRestored=false;snapshotSavedAt=0;latestReport=null;currentJobConfig=cfg;currentJobReportId="";running=true;updateRunButtons();lastDraw=0;final long op=++operation,gen=generation;final String toolKind=kind;final AtomicReference<Report> latest=new AtomicReference<>();final long[] retainedAt={0};
        if(progress!=null){progress.setIndeterminate(true);progress.setVisibility(View.VISIBLE);}if(state!=null)state.setText("Running · "+name+" · use Stop to cancel");
        final boolean sound=toolKind.equals("ping")&&cfg!=null&&cfg.optBoolean("ping_sound",false);final String[] sounded={""};
        final Task local=new Task(r->{latest.set(r);long now=android.os.SystemClock.elapsedRealtime();if(gen==generation&&op==operation){latestReport=r;if(retainedTool(toolKind)&&now-retainedAt[0]>=3000){retainedAt[0]=now;store.snapshot(toolKind,r,cfg);}}if(now-lastDraw<750)return;lastDraw=now;handler.post(()->{if(gen==generation&&op==operation){currentJobReportId=r.id;renderResult(r);updateProgress(r);if(sound)synchronized(r){if(!r.rows.isEmpty()){List<String> last=r.rows.get(r.rows.size()-1);if(last.size()>3&&!last.get(0).equals(sounded[0])&&!last.get(3).equals("—")){sounded[0]=last.get(0);tone();}}}if(state!=null)state.setText(runningText(toolKind,r));}});});task=local;
        worker.execute(()->{
            Report result=null;String message="Completed";Task.RouteException routeProblem=null;
            try{if(cfg!=null&&cfg.has("network_id"))NetworkRoute.attach(this,cfg.optString("network_id",""),local);result=job.run(local);if(local.isCancelled())message="Stopped";}
            catch(Exception e){result=latest.get();routeProblem=local.isCancelled()?null:Task.routeFailure(e);message=local.isCancelled()?"Stopped":"Could not finish: "+explain(e);if(result==null)result=new Report(name,cfg==null?"":cfg.optString("target",""),"Status","Details");result.note(message);}
            if(result==null)result=new Report(name,"","Status","Details");
            result.note("Status: "+message);if(cfg!=null)result.note("Parameters: "+cfg.toString());
            if(save||toolKind.equals("signal")){store.save(result);if(cfg!=null)store.prefs.edit().putString("config_"+result.id,cfg.toString()).apply();}
            final Report done=result;final String finalMessage=message;final Task.RouteException routingError=routeProblem;local.cancel();
            handler.post(()->{if(gen!=generation||op!=operation)return;running=false;task=null;latestReport=done;updateRunButtons();currentJobReportId=done.id;renderResult(done);persistSnapshot();if(progress!=null)progress.setVisibility(View.INVISIBLE);if(state!=null)state.setText(toolKind.equals("network")?"Live connections · tap a network for details":completionText(toolKind,done,finalMessage));if(toolKind.equals("wifi"))scheduleWifi();if(routingError!=null&&cfg!=null&&routingError.canUseSystem)showRoutingRecovery(routingError);});
        });
    }
    private String explain(Exception e){Task.RouteException route=Task.routeFailure(e);if(route!=null)return route.getMessage();Throwable cause=e;for(int i=0;i<8&&cause.getCause()!=null;i++)cause=cause.getCause();String message=cause.getMessage();if(message==null||message.trim().isEmpty())message="The operation could not complete. Check the target and connection, then try again.";message=message.replaceAll("(?:java|javax|android)\\.[A-Za-z0-9_.$]+(?:Exception|Error):\\s*","");if(cause instanceof SecurityException)message="Android denied access. Check app permissions and the selected network. "+message;return message;}
    private void showRoutingRecovery(Task.RouteException failure){
        new AlertDialog.Builder(this).setTitle(failure.title).setMessage(failure.getMessage()+"\n\nUse Android routing to retry the current target through the phone’s normal routing, including any VPN. The scan target stays the same. This does not bypass VPN policy.").setPositiveButton("Use Android routing",(a,b)->{if(kind.equals("lan")&&lanRoute!=null){lanRoute.setSelection(0);updateDetectedLan();}else{NetworkPicker picker=networkPickers.get("outgoing_network");if(picker==null)return;picker.selectedKey="";picker.selectedLabel="System default routing";populateNetworkPicker(picker);}rememberInputs();executeTool(false);}).setNegativeButton("Keep selected network",null).show();
    }
