    private String completionText(String tool,Report report,String message){if(!message.equals("Completed"))return message+" · partial results kept";String when=DateFormat.getTimeInstance(DateFormat.SHORT).format(new java.util.Date());if(tool.equals("lan"))return "Scan saved at "+when+" · tap a device for actions";if(tool.equals("wifi"))return "Wi-Fi snapshot saved at "+when+" · tap Scan to refresh";if(tool.equals("ports"))return countLabel(openPortCount(report),"open port","open ports")+" · check completed";return "Completed · "+countLabel(rowCount(report),tool.equals("signal")?"sample":"result",tool.equals("signal")?"samples":"results")+" · saved locally";}
