    private String wifiSecurity(String value){String security=value.toUpperCase(Locale.ROOT);if(security.contains("SAE")||security.contains("WPA3"))return security.contains("PSK")?"WPA2 / WPA3":"WPA3";if(security.contains("OWE"))return "Enhanced Open";if(security.contains("EAP"))return "Enterprise security";if(security.contains("WPA2")||security.contains("RSN"))return "WPA2";if(security.contains("WPA"))return "WPA";if(security.contains("WEP"))return "WEP";if(!usable(value))return "Security unavailable";return "Open network";}
    private String wifiAge(String value){double age=parse(value,Double.NaN);if(Double.isNaN(age))return "Age unavailable";if(snapshotRestored&&snapshotSavedAt>0)age+=Math.max(0,System.currentTimeMillis()-snapshotSavedAt)/1000.0;return age<60?"seen "+Math.round(age)+" s ago":age<3600?"seen "+Math.round(age/60)+" min ago":"seen "+String.format(Locale.US,"%.1f",age/3600)+" h ago";}
    private String portStatus(String value){if(value.equalsIgnoreCase("Open"))return "Open · accepts TCP connections";if(value.equalsIgnoreCase("Closed"))return "Closed · device refused the connection";if(value.toLowerCase(Locale.ROOT).contains("time"))return "No reply · may be filtered or unreachable";return value;}
