        boolean graph=yes("wifi_graph");if(graph){while(wifiCharts.size()<3){ChartView chart=new ChartView(this);chart.colors(dark);chart.setFocusable(false);wifiCharts.add(chart);chartHost.addView(chart,new LinearLayout.LayoutParams(-1,d(170)));}final List<List<String>> plotted=new ArrayList<>(rows);for(int b=0;b<3;b++){ChartView chart=wifiCharts.get(b);boolean show=band.equals("All bands")||band.startsWith(b==0?"2.4":b==1?"5 ":"6 ");chart.setVisibility(show?View.VISIBLE:View.GONE);chart.setWifi(rows,b,index->{if(index<plotted.size())rowDetails(r,plotted.get(index));});}}else for(ChartView chart:wifiCharts)chart.setVisibility(View.GONE);
