        LinearLayout body=col();body.setPadding(d(20),d(12),d(20),d(15));if(kind.equals("lan")){TagFlow facts=new TagFlow(this);for(DeviceFacts.Tag tag:DeviceFacts.tags(values,report.columns))facts.addView(capabilityTag(tag.label,tag.kind,tag.evidence));body.addView(facts,new LinearLayout.LayoutParams(-1,-2));gap(body,12);}TextView info=text(details.toString(),14,ink);info.setTextIsSelectable(true);body.addView(info);
