    private JSONObject routeConfigurationFor(Report report,List<String> row){
        JSONObject source=configurationFor(report),result=new JSONObject();String id=source.optString("network_id",""),key=source.optString("network_key",source.optString("lan_network",source.optString("outgoing_network",""))),label=source.optString("network_label","System default routing"),subnet=source.optString("network_subnet","");boolean specified=source.has("network_id");
        if(inferKind(report.title).equals("network")){List<List<String>> all;synchronized(report){all=new ArrayList<>(report.rows);}List<String> header=null;for(List<String> item:all){if(!item.isEmpty()&&item.get(0).equals("[NETWORK]"))header=item;if(item==row||item.equals(row))break;}if(header!=null&&header.size()>2&&(header.get(2).startsWith("network:")||header.get(2).startsWith("interface:"))){id=header.get(2);label=header.get(1);key="";subnet="";specified=true;}}
        if(!specified)return null;
        if(!id.isEmpty()&&key.isEmpty()){NetworkInventory.Connection connection=NetworkInventory.lookup(this,id);if(connection!=null){if(connection.observedOnly)for(NetworkInventory.Connection other:NetworkInventory.snapshot(this))if(other.canBind()&&other.interfaceName.equals(connection.interfaceName)){connection=other;break;}String address=connection.ipv4Cidrs.length==0?"":connection.ipv4Cidrs[0];if(!subnet.isEmpty())for(String candidate:connection.ipv4Cidrs)if(NetworkInventoryLogic.ipv4Range(candidate).equals(subnet)){address=candidate;break;}key=connection.kind+"|"+connection.interfaceName+"|"+address;id=connection.id;subnet=NetworkInventoryLogic.ipv4Range(address);label=connection.title();}else key="unavailable:"+id;}
        try{result.put("outgoing_network",key).put("outgoing_network_label",label).put("network_id",id).put("network_label",label).put("network_subnet",subnet);}catch(Exception ignored){}return result;
    }
    private JSONObject configurationFor(Report r){String saved=store.prefs.getString("config_"+r.id,"");try{if(!saved.isEmpty())return new JSONObject(saved);}catch(Exception ignored){}if(currentJobConfig!=null&&r.id.equals(currentJobReportId))return currentJobConfig;synchronized(r){for(String note:r.notes)if(note.startsWith("Parameters: "))try{return new JSONObject(note.substring("Parameters: ".length()));}catch(Exception ignored){}}if(page.equals("tool")&&!inputs.isEmpty()&&current!=null&&r.id.equals(current.id))return config();JSONObject cfg=new JSONObject();try{cfg.put("kind",inferKind(r.title));cfg.put("target",r.target);}catch(Exception ignored){}return cfg;}
    private String inferKind(String title){String lower=title.toLowerCase(Locale.ROOT);if(lower.contains("public"))return "public";if(lower.contains("signal"))return "signal";if(lower.contains("wi-fi"))return "wifi";if(lower.contains("traceroute"))return "trace";if(lower.contains("port"))return "ports";if(lower.contains("dns")&&!lower.contains("mdns"))return "dns";if(lower.contains("whois")||lower.contains("rdap")||lower.contains("registration"))return "registration";if(lower.contains("speed"))return "speed";if(lower.contains("mdns")||lower.contains("bonjour"))return "mdns";if(lower.contains("upnp")||lower.contains("dlna"))return "upnp";if(lower.contains("wake"))return "wol";if(lower.contains("lan"))return "lan";if(lower.contains("ping"))return "ping";return "network";}
