        LinearLayout data=settingsGroup("Local data");pair(data,"Clear history",()->confirm("Delete all history?","This removes archived diagnostic reports. Last LAN, Wi-Fi and signal views are kept separately.",()->{store.clearHistory();removeConfigPreferences();toast("History cleared");}),"Clear favorites",()->confirm("Delete all favorites?","Saved targets and wake configurations will be removed.",()->{store.clearFavorites();toast("Favorites cleared");}));
        addButton(data,"Clear saved tool views",()->confirm("Delete saved tool views?","This removes the last LAN devices, Wi-Fi analyzer snapshot and signal-monitor samples. History, favorites and Nearby finder observations are kept.",()->{store.clearSnapshots();toast("Saved LAN and signal views cleared");}));
        addButton(data,"Clear shared export cache",()->{File dir=new File(getCacheDir(),"exports");File[]files=dir.listFiles();int n=0;if(files!=null)for(File f:files)if(f.isFile()&&f.delete())n++;toast(n+" cached export files removed");});addButton(data,"Manage exported files",()->{try{startActivity(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE));}catch(Exception e){error("No system document picker is available.");}});note(data,"History and last tool views are separate local copies. Clear both to remove retained LAN / signal results. Nearby finder has its own clear action. Files saved through Android’s document picker are managed by their chosen storage provider.");
        LinearLayout privacy=settingsGroup("Privacy & Android limits");addButton(privacy,"Open-source notices",this::openSourceNotices);addButton(privacy,"Optional cellular permission",this::phonePermission);note(privacy,"No account, analytics, or automatic upload of local inventories. Public IP / provider, registration and speed tests contact external services only when selected, as disclosed on those screens. DNS names are sent to the selected resolver.\n\nAndroid can redact Wi-Fi / cellular values, throttle scans, restrict MAC addresses and deny native ICMP facilities. LAN probes cannot guarantee discovery of every device. Missing traceroute hops are not proof of broken routing. TCP timeouts do not prove filtering. Wi-Fi overlap is an estimate; no RF airtime is measured. A sent wake packet does not prove power-on.\n\nNetwork jobs stop when the app moves to the background. FieldKit requires no root privileges.");
