    private void openSourceNotices(){showNotice("third_party_notices.txt","Open-source notices",true);}
    private void showNotice(String asset,String title,boolean inventory){
        new Thread(()->{try(InputStream input=getAssets().open(asset);ByteArrayOutputStream bytes=new ByteArrayOutputStream()){byte[] block=new byte[8192];int n;while((n=input.read(block))!=-1)bytes.write(block,0,n);String notice=new String(bytes.toByteArray(),StandardCharsets.UTF_8);handler.post(()->{if(isFinishing())return;TextView text=text(notice,12,ink);text.setTextIsSelectable(true);text.setPadding(d(18),d(12),d(18),d(12));ScrollView view=new ScrollView(this);view.addView(text);AlertDialog.Builder dialog=new AlertDialog.Builder(this).setTitle(title).setView(view).setPositiveButton("Close",null);if(inventory)dialog.setNeutralButton("License texts",(a,b)->{try{String[] files=getAssets().list("licenses");if(files!=null&&files.length>0)new AlertDialog.Builder(this).setTitle("License texts").setItems(files,(c,selected)->showNotice("licenses/"+files[selected],files[selected],false)).setNegativeButton("Close",null).show();}catch(IOException failure){toast("License text could not be opened");}});dialog.show();});}catch(IOException failure){handler.post(()->toast("Notice text could not be opened"));}},"fieldkit-notices").start();
    }
